for skip, cap in [(0,None),(0,0),(0,1),(0,2),(1,1),(-1,1),(2,None),(0,-1)]:
 s=set(sorted(subjects)[skip:]); total=sum(x in s for x in rows); remaining=dict.fromkeys(s,0); jobs=[]
 for x in rows:
