  jobs.append(x); remaining[x]+=1
 done=[]
 for x in reversed(jobs):
  remaining[x]-=1
  if remaining[x]==0: done.append(x)
 try: aggregate=100*len(jobs)/len(jobs)
 except ZeroDivisionError: aggregate='ZeroDivisionError'
 print(skip,cap,sorted(s),total,dict(Counter(jobs)),total-len(jobs),done,aggregate)
